import Foundation

/// Decides whether a pasteboard change may be recorded. Password managers and other apps tag what they
/// put on the pasteboard with marker types (the nspasteboard.org conventions); anything carrying one is
/// never stored, however it got there.
public enum PasteboardFilter {
    /// The marker types that mean "do not record this".
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    /// 1Password has used several versions of its marker; any type under this prefix counts.
    private static let skippedPrefixes = ["com.agilebits.onepassword"]

    /// False when any of `types` (the pasteboard's type identifiers) is a do-not-record marker.
    public static func shouldRecord(types: [String]) -> Bool {
        !types.contains { type in
            skippedTypes.contains(type) || skippedPrefixes.contains { type.hasPrefix($0) }
        }
    }

    /// `shouldRecord(types:)` plus the user's list of ignored apps (matched on the source app's bundle id).
    public static func shouldRecord(types: [String], sourceBundleID: String?, ignoredBundleIDs: [String]) -> Bool {
        if let sourceBundleID, ignoredBundleIDs.contains(sourceBundleID) { return false }
        return shouldRecord(types: types)
    }
}
